//! Shared credit identifies the exact generator build that emitted HTML.
use super::markup::html_escape as esc;
pub(super) fn html() -> String {
    format!(
        "Generated by <a href=\"https://ekgf.github.io/grapharch/\" \
         title=\"{}\">Grapharch {}</a><span class=\"generator-build\" \
         data-build-channel=\"{}\" data-build-number=\"{}\" \
         data-build-attempt=\"{}\" data-generator-revision=\"{}\" \
         data-build-run=\"{}\"></span>",
        esc(env!("GRAPHARCH_BUILD_DETAILS")),
        esc(env!("GRAPHARCH_BUILD_LABEL")),
        esc(env!("GRAPHARCH_BUILD_CHANNEL")),
        esc(env!("GRAPHARCH_BUILD_NUMBER")),
        esc(env!("GRAPHARCH_BUILD_ATTEMPT")),
        esc(env!("GRAPHARCH_GENERATOR_REVISION")),
        esc(env!("GRAPHARCH_BUILD_RUN_URL"))
    )
}
